// Ambil pesan dari payload agen dan bentuk parameter untuk dm_record; kenali perintah teks.
const p = $('Webhook agen').first().json.body;
const MAX_B64 = 11 * 1024 * 1024;
const mime = p.mimetype || '';
const isDoc = /^document/i.test(p.message_type || '') ||
  /(spreadsheet|excel|csv|pdf|msword|officedocument)/i.test(mime);
// Hanya file tabel (xlsx/xls/csv) yang diunggah ke folder "RC 0"; PDF dan lainnya hanya dicatat.
const isSheet = /(spreadsheet|excel|csv)/i.test(mime);
const b64 = isSheet ? (p.media_base64 || null) : null;
const tooBig = !!(b64 && b64.length > MAX_B64);
const ext = /csv/i.test(mime) ? 'csv' : (/spreadsheetml|openxml/i.test(mime) ? 'xlsx' : 'xls');
const wib = new Date(Date.now() + 7 * 3600 * 1000).toISOString().slice(0, 16).replace('T', ' ').replace(':', '');
const cap = String(p.raw_text ?? p.text ?? '').replace(/[^A-Za-z0-9 _.-]/g, '').trim().slice(0, 40);
const fileName = ('RC0 ' + (cap ? cap + ' ' : '') + wib + '.' + ext);
const t = String(p.raw_text ?? p.text ?? '').trim();
const tl = t.toLowerCase();
let cmd = 'catat', arg = '';
if (!isDoc) {
  if (/^(proses|cek harga|update harga|mulai)\b/.test(tl)) cmd = 'proses';
  else if (/^setuju\b/.test(tl)) { cmd = 'setuju'; arg = tl.replace(/^setuju\s*/, ''); }
  else if (/^(pdf|buat pdf|fase 2)\b/.test(tl)) { cmd = 'pdf'; arg = t.replace(/^(pdf|buat pdf|fase 2)\s*/i, ''); }
  else if (/^(minggu baru|rotasi)\b/.test(tl)) { cmd = 'rotasi'; arg = t.replace(/^(minggu baru|rotasi)\s*/i, ''); }
  else if (/^(tes google|tes koneksi)\b/.test(tl)) cmd = 'tes';
  else if (/^batal\b/.test(tl)) cmd = 'batal';
  else if (/^(bantuan|menu|help)\b/.test(tl)) cmd = 'bantuan';
}
return [{ json: {
  cmd, arg, task_id: p.task_id, chat_id: p.chat_id, too_big: tooBig,
  upload: !!b64 && !tooBig, b64: tooBig ? null : b64, file_name: fileName, mime,
  p: {
    message_id: p.message_id, chat_id: p.chat_id, sender: p.sender, push_name: p.push_name,
    text: p.raw_text ?? p.text ?? '', message_type: p.message_type, mimetype: p.mimetype,
  },
} }];

// Ubah base64 dari WhatsApp menjadi file biner untuk node Google Drive.
const s = $('Siapkan').first().json;
const buf = Buffer.from(s.b64, 'base64');
const bin = await this.helpers.prepareBinaryData(buf, s.file_name, s.mime);
return [{ json: { file_name: s.file_name }, binary: { data: bin } }];

// Susun balasan singkat dari hasil dm_record dan hasil unggah ke Drive. Diam kalau tidak ada balasan.
const s = $('Siapkan').first().json;
const r = $('Catat (RPC dm_record)').first().json;
const res = Array.isArray(r) ? (r[0] || {}) : ((r && 'reply' in r) ? r : (r?.dm_record || r || {}));
let reply = res.reply || null;
if (s.too_big) {
  reply = '⚠️ File terlalu besar untuk disimpan (maks sekitar 8 MB). Coba kirim ulang yang lebih kecil.';
} else if (s.upload) {
  let d = null;
  try { d = $('Unggah ke Drive').first().json; } catch (e) {}
  if (d && d.id && !d.error) reply = '✅ File tersimpan di Drive (folder RC 0): ' + s.file_name + ' | ' + (res.reply || '');
  else reply = '⚠️ File diterima tapi gagal disimpan ke Drive. Saya catat dulu, mohon kabari Claude. ' + (res.reply || '');
}
return [{ json: { chat_id: s.chat_id, task_id: s.task_id, reply, kind: res.kind || 'text' } }];

const e = $input.first().json;
const er = e.error || e;
const msg = [er.message, er.description].filter(Boolean).join(' – ') || JSON.stringify(e).slice(0, 300);
return [{ json: { reply: '⚠️ Gagal: ' + String(msg).slice(0, 450) + '\nMohon kabari Claude.' } }];

const list = $('Proses: daftar file').first().json.files || [];
const mf = ($('Proses: cari master').first().json.files || []).find(f => f.name.startsWith('[MASTER] Harga Supplier'));
if (!mf) return [{ json: { ok: false, reply: '⚠️ Master "[MASTER] Harga Supplier ..." tidak ditemukan di Drive.' } }];
const cutoff = Date.now() - 21 * 864e5;
const c = list.filter(f => new Date(f.createdTime).getTime() > cutoff).slice(0, 4);
if (!c.length) return [{ json: { ok: false, reply: '⚠️ Belum ada file RC 0 dalam 3 minggu terakhir. Kirim dulu file RC 0 ke grup ini.' } }];
return c.map((f, i) => ({ json: { ok: true, fileId: f.id, fname: f.name, created: f.createdTime, idx: i } }));

// ── Inti perhitungan (dipakai node Code dan diuji lokal) ──────────────────────
const norm = x => String(x == null ? '' : x).replace(/\s+/g, ' ').trim().toLowerCase();
const SYN = [['saos', 'saus'], ['jintan', 'jinten'], ['fres ', 'fresh '], ['mozarella', 'mozzarella']];
const STOP = new Set(['merk', 'kg', 'pcs', 'gr', 'gram', '1kg', '1', 'l', 'ml', 'liter', 'botol', 'saset', 'sachet', 'cap', 'raw', 'material', 'dan', 'tanpa']);
const ALIAS = { 'jamur salju/snow': 'jamur salju' };
const TABS = ['SAYURAN', 'KARBOHIDRAT', 'PROTEIN', 'BUMBU', 'SEMBAKO', 'BUAH & SUSU', 'BAHAN TAMBAHAN'];
const UTARA = ['pringapus', 'bawen', 'ambarawa', 'banyubiru'];
const SELATAN = ['kranggan', 'kedungsari', 'grabag', 'pituruh'];

function key(x) {
  let s = String(x || '').toLowerCase();
  for (const [a, b] of SYN) s = s.split(a).join(b);
  s = s.replace(/[^a-z0-9 ]/g, ' ').replace(/(\d+)\s*(gr|g|gram)\b/g, '$1gr');
  return s.split(/\s+/).filter(t => t && !STOP.has(t)).sort().join(' ');
}
function dice(a, b) {
  a = key(a); b = key(b); if (a.length < 2 || b.length < 2) return 0;
  const bg = s => { const m = new Map(); for (let i = 0; i < s.length - 1; i++) { const g = s.slice(i, i + 2); m.set(g, (m.get(g) || 0) + 1); } return m; };
  const A = bg(a), B = bg(b); let inter = 0;
  for (const [g, c] of A) inter += Math.min(c, B.get(g) || 0);
  return 2 * inter / ((a.length - 1) + (b.length - 1));
}
function toGrid(j) {
  const out = {};
  for (const s of (j.sheets || [])) {
    const rows = (((s.data || [])[0] || {}).rowData || []).map(r => ((r && r.values) || []).map(v => {
      const e = v && v.effectiveValue; if (!e) return null;
      if ('numberValue' in e) return e.numberValue; if ('stringValue' in e) return e.stringValue;
      if ('boolValue' in e) return e.boolValue; return null;
    }));
    out[s.properties.title] = rows;
  }
  return out;
}
const rp = n => (n < 0 ? '-' : '') + String(Math.round(Math.abs(n))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

function masterItems(rows) {
  const out = [];
  (rows || []).forEach((r, i) => {
    if (i === 0) return; const nm = r[1], pr = r[2];
    if (nm && typeof pr === 'number') out.push({ row: i + 1, name: String(nm).trim(), k: norm(nm), price: pr });
  });
  return out;
}
function rcRows(rows) {
  let hi = -1, cols = [];
  for (let i = 0; i < Math.min(12, rows.length); i++) {
    const js = []; (rows[i] || []).forEach((c, j) => { if (norm(c) === 'rc 0' && j > 0) js.push(j); });
    if (js.length) { hi = i; cols = js; break; }
  }
  if (hi < 0) return [];
  const out = [];
  for (let i = hi + 1; i < rows.length; i++) {
    const r = rows[i] || [];
    for (const ci of cols) { const nm = r[ci - 1], v = r[ci]; if (nm && typeof v === 'number') out.push({ name: String(nm).trim(), v, row: i + 1 }); }
  }
  return out;
}
function findMaster(items, name, pred) {
  const nm = ALIAS[norm(name)] || name;
  const k = norm(nm); const cand = items.filter(pred);
  let m = cand.filter(x => x.k === k); if (m.length) return { item: m[0], how: 'exact' };
  const kk = key(nm); m = cand.filter(x => key(x.name) === kk); if (m.length === 1) return { item: m[0], how: 'key' };
  let best = null, bs = 0; for (const x of cand) { const s = dice(nm, x.name); if (s > bs) { bs = s; best = x; } }
  if (best && bs >= 0.85) return { item: best, how: 'mirip', score: bs };
  return null;
}
function ayamKind(n) {
  n = norm(n);
  if (/giling/.test(n)) return 'giling'; if (/dadu/.test(n)) return 'dadu'; if (/katsu/.test(n)) return 'katsu';
  if (/tanpa kulit/.test(n)) return 'tanpakulit'; if (/(filet|fillet).*(dada|paha)|(dada|paha).*(filet|fillet)/.test(n)) return 'filet';
  if (/potong/.test(n)) return 'potong'; return null;
}
const EXCLUDE = [[/^bihun/i, 'Bihun tidak diubah (aturan tetap)'], [/minyak goreng/i, 'Minyak goreng dilewati']];

function classify(gridsList) {
  let sepakat = null, sawangan = null;
  for (const f of gridsList) {
    const t = Object.keys(f.grid);
    const isSep = t.includes('PROTEIN') && t.includes('SAYURAN');
    if (isSep && !sepakat) sepakat = f; else if (!isSep && !sawangan) sawangan = f;
  }
  return { sepakat, sawangan };
}

function buildPlan(masterG, sep, saw) {
  const items = [], unsure = [], unmatched = [], skipped = [], targets = new Map();
  const add = (e, reasons) => {
    const tk = e.tab + '|' + e.row;
    if (targets.has(tk)) { if (targets.get(tk).new !== e.new) reasons.push('nama dobel di RC 0, nilainya beda'); else return; }
    else targets.set(tk, e);
    if (e.old > 0 && Math.abs(e.new - e.old) / e.old > 0.5) reasons.push('selisih >50%');
    if (reasons.length) { e.why = reasons.join('; '); unsure.push(e); } else items.push(e);
  };
  for (const tab of TABS) {
    const mi = masterItems(masterG[tab]);
    if (sep && sep.grid[tab]) {
      for (const rc of rcRows(sep.grid[tab])) {
        const ex = EXCLUDE.find(([re]) => re.test(rc.name)); if (ex) { skipped.push(rc.name + ' (' + ex[1] + ')'); continue; }
        if (/^ayam /i.test(rc.name)) continue;
        const pred = x => !/^[su] ?ayam/i.test(x.name) && !(tab === 'SAYURAN' && x.k.endsWith(' s'));
        const m = findMaster(mi, rc.name, pred);
        if (!m) { unmatched.push(rc.name); continue; }
        if (m.item.price === rc.v) continue;
        add({ tab, row: m.item.row, name: m.item.name, old: m.item.price, new: rc.v, src: 'sepakat', via: m.how === 'key' ? rc.name : null },
            m.how === 'mirip' ? ['nama mirip dengan "' + rc.name + '"'] : []);
      }
    }
  }
  // Sawangan: item berakhiran " S" di blok sayur Sawangan
  if (saw) {
    const mi = masterItems(masterG['SAYURAN']);
    const rows = saw.grid[Object.keys(saw.grid)[0]];
    for (const rc of rcRows(rows)) {
      const ex = EXCLUDE.find(([re]) => re.test(rc.name)); if (ex) continue;
      const m = findMaster(mi, rc.name + ' S', x => x.k.endsWith(' s'));
      if (!m) { unmatched.push(rc.name + ' (Sawangan)'); continue; }
      if (m.item.price === rc.v) continue;
      add({ tab: 'SAYURAN', row: m.item.row, name: m.item.name, old: m.item.price, new: rc.v, src: 'sawangan', via: m.how === 'key' ? rc.name : null },
          m.how === 'mirip' ? ['nama mirip dengan "' + rc.name + '"'] : []);
    }
  }
  // Ayam: harga tertinggi per area
  if (sep && sep.grid['PROTEIN']) {
    const rows = sep.grid['PROTEIN']; let hi = -1, cj = -1;
    for (let i = 0; i < Math.min(30, rows.length) && hi < 0; i++) {
      (rows[i] || []).forEach((c, j) => { if (hi < 0 && norm(c) === 'item' && norm((rows[i] || [])[j + 1]) === 'pringapus') { hi = i; cj = j; } });
    }
    if (hi >= 0) {
      const areas = []; for (let j = cj + 1; j < rows[hi].length && rows[hi][j]; j++) areas.push([j, norm(rows[hi][j])]);
      const best = {};
      for (let i = hi + 1; i < rows.length && (rows[i] || [])[cj]; i++) {
        const kind = ayamKind(rows[i][cj]); if (!kind) continue;
        const mx = names => Math.max(-1, ...areas.filter(a => names.includes(a[1])).map(a => rows[i][a[0]]).filter(v => typeof v === 'number'));
        best[kind] = { u: mx(UTARA), s: mx(SELATAN) };
      }
      const pm = masterItems(masterG['PROTEIN']);
      for (const x of pm) {
        const g = /^s ?ayam/i.test(x.name) ? 's' : (/^u ?ayam/i.test(x.name) ? 'u' : null); if (!g) continue;
        const kind = ayamKind(x.name); const b = best[kind]; if (!b || b[g] <= 0) continue;
        if (b[g] !== x.price) add({ tab: 'PROTEIN', row: x.row, name: x.name, old: x.price, new: b[g], src: (g === 's' ? 'Selatan' : 'Utara') + ', tertinggi' }, []);
      }
    }
  }
  const order = t => TABS.indexOf(t);
  const cmp = (a, b) => order(a.tab) - order(b.tab) || a.row - b.row;
  items.sort(cmp); unsure.sort(cmp);
  let n = 0; items.forEach(e => e.n = ++n); unsure.forEach(e => e.n = ++n);
  return { items, unsure, unmatched, skipped };
}

function weekInfo(masterName, sep) {
  const m = /Harga Supplier\s+(\S+)\s+Week\s*(\d+)/i.exec(masterName || '');
  let dates = null;
  if (sep) for (const t of Object.keys(sep.grid)) {
    for (const r of sep.grid[t].slice(0, 6)) for (const c of (r || [])) {
      const d = /(\d{1,2})\s*-\s*(\d{1,2})\s*(jan|feb|mar|apr|mei|jun|jul|agu|sep|okt|nov|des)/i.exec(String(c || ''));
      if (d && !dates) dates = d[1] + '-' + d[2];
    }
  }
  return { month: m ? m[1] : null, week: m ? m[2] : null, dates };
}

function formatPlan(plan) {
  const L = [];
  L.push('📋 *Rencana update harga RC 0*');
  L.push(plan.masterName + (plan.dates ? ' (' + plan.dates + ')' : ''));
  L.push('');
  const line = e => e.n + '. ' + e.tab + ' – ' + e.name + ': ' + rp(e.old) + ' → ' + rp(e.new) + ' (' + (e.new >= e.old ? '+' : '') + rp(e.new - e.old) + ')' + (e.src !== 'sepakat' ? ' [' + e.src + ']' : '') + (e.via ? ' (di RC 0: "' + e.via.trim() + '")' : '');
  L.push('*Akan diubah (' + plan.items.length + '):*');
  plan.items.forEach(e => L.push(line(e)));
  if (plan.unsure.length) {
    L.push(''); L.push('⚠️ *Perlu keputusan (TIDAK dimasukkan kecuali kamu setujui):*');
    plan.unsure.slice(0, 15).forEach(e => L.push(line(e) + ' — ' + e.why));
    if (plan.unsure.length > 15) L.push('…dan ' + (plan.unsure.length - 15) + ' lagi');
  }
  if (plan.skipped.length) { L.push(''); L.push('Dilewati sesuai aturan: ' + plan.skipped.slice(0, 6).join('; ')); }
  if (plan.unmatched.length) L.push('Tidak ada di master (dilewati): ' + plan.unmatched.length + ' item.');
  L.push('');
  L.push('Balas: *setuju* | *setuju kecuali 3,5* | *setuju + 31* (masukkan yang perlu keputusan) | *batal*');
  return L.join('\n');
}

const masterG = toGrid($('Proses: baca master').first().json);
const metas = $('Proses: pilih').all().map(i => i.json);
const reads = $('Proses: baca RC0').all().map(i => i.json);
const files = reads.map((j, i) => ({ name: metas[i].fname, id: metas[i].fileId, grid: toGrid(j) }));
const { sepakat, sawangan } = classify(files);
if (!sepakat) return [{ json: { reply: '⚠️ File RC 0 sepakat belum ketemu (yang berisi tab SAYURAN dan PROTEIN). Kirim ke grup lalu ketik *proses* lagi.' } }];
const mf = ($('Proses: cari master').first().json.files || []).find(f => f.name.startsWith('[MASTER] Harga Supplier'));
const pl = buildPlan(masterG, sepakat, sawangan);
const wk = weekInfo(mf.name, sepakat);
const plan = { status: 'pending', masterId: mf.id, masterName: mf.name, month: wk.month, week: wk.week, dates: wk.dates,
  files: { sepakat: sepakat.name, sawangan: sawangan ? sawangan.name : null }, items: pl.items, unsure: pl.unsure,
  skipped: pl.skipped, unmatched: pl.unmatched, createdAt: new Date().toISOString() };
let reply = formatPlan(plan);
reply += '\n\nFile dipakai: ' + sepakat.name + (sawangan ? ' + ' + sawangan.name : ' (file Sawangan BELUM ada, harga Sawangan tidak ikut)');
return [{ json: { reply, plan } }];

const plan = $json.val;
if (!plan || !plan.items) return [{ json: { ok: false, reply: 'Belum ada rencana yang menunggu. Ketik *proses* dulu.' } }];
if (plan.status === 'applied') return [{ json: { ok: false, reply: 'Rencana ini sudah ditulis ke master. Ketik *pdf* untuk lanjut, atau *proses* untuk rencana baru.' } }];
const a = String($('Siapkan').first().json.arg || '');
const nums = s => (s ? (s.match(/\d+/g) || []).map(Number) : []);
const ex = nums((/kecuali\s*([\d,\s]+)/.exec(a) || [])[1]);
const inc = nums((/(?:\+|masukkan|tambah)\s*([\d,\s]+)/.exec(a) || [])[1]);
const chosen = plan.items.filter(e => !ex.includes(e.n)).concat(plan.unsure.filter(e => inc.includes(e.n)));
if (!chosen.length) return [{ json: { ok: false, reply: 'Tidak ada harga yang dipilih untuk ditulis.' } }];
const ranges = chosen.map(e => "'" + e.tab + "'!C" + e.row);
return [{ json: { ok: true, plan, chosen, ranges, excluded: ex, included: inc,
  url: 'https://sheets.googleapis.com/v4/spreadsheets/' + plan.masterId + '/values:batchGet?valueRenderOption=UNFORMATTED_VALUE&ranges=' + ranges.map(encodeURIComponent).join('&ranges=') } }];

const d = $('Setuju: susun').first().json;
const vr = $json.valueRanges || [];
const writes = [], blocked = [];
d.chosen.forEach((e, i) => {
  const cur = (((vr[i] || {}).values || [])[0] || [])[0];
  if (Number(cur) === Number(e.old)) writes.push(e); else blocked.push(e.n + '. ' + e.name + ' (sekarang ' + cur + ', rencana mengira ' + e.old + ')');
});
const body = { valueInputOption: 'RAW', data: writes.map(e => ({ range: "'" + e.tab + "'!C" + e.row, values: [[e.new]] })) };
return [{ json: { ok: writes.length > 0, writes, blocked, body, plan: d.plan, reply: 'Tidak ada yang bisa ditulis: nilai di master sudah beda dari rencana. ' + blocked.join('; ') } }];

const d = $('Setuju: cek lama').first().json;
const all = $('Setuju: susun').first().json.chosen;
const vr = $json.valueRanges || [];
let ok = 0; const bad = [];
all.forEach((e, i) => {
  const want = d.writes.find(w => w.n === e.n); if (!want) return;
  const cur = (((vr[i] || {}).values || [])[0] || [])[0];
  if (Number(cur) === Number(e.new)) ok++; else bad.push(e.n + '. ' + e.name + ' (hasil ' + cur + ', seharusnya ' + e.new + ')');
});
const plan = d.plan; plan.status = bad.length ? 'pending' : 'applied'; plan.appliedAt = new Date().toISOString();
let reply = (bad.length ? '⚠️ ' : '✅ ') + ok + ' dari ' + d.writes.length + ' harga tertulis dan terverifikasi di ' + plan.masterName + '.';
if (d.blocked.length) reply += '\nDilewati karena nilai di master sudah berubah: ' + d.blocked.join('; ');
if (bad.length) reply += '\nBELUM cocok: ' + bad.join('; ') + '\nMohon kabari Claude.';
else reply += '\nLanjut: ketik *pdf* untuk membuat 3 PDF PAGU DAPUR.';
return [{ json: { reply, plan } }];

const plan = $json.val || {};
const arg = String($('Siapkan').first().json.arg || '');
let month = plan.month, week = plan.week, dates = plan.dates;
const a = /(\S+)\s+week\s*(\d+)\s+(\d{1,2})\s*-\s*(\d{1,2})/i.exec(arg);
if (a) { month = a[1]; week = a[2]; dates = a[3] + '-' + a[4]; }
if (!month || !week || !dates) return [{ json: { ok: false, reply: 'Saya belum tahu minggu dan tanggalnya. Ketik *proses* dulu, atau tulis: *pdf November Week 4 22-26*' } }];
month = month.charAt(0).toUpperCase() + month.slice(1).toLowerCase();
const base = ' PAGU DAPUR - ' + month + ' Week ' + week + '(' + dates + month + ').pdf';
return [{ json: { ok: true, label: month + ' Week ' + week + ' (' + dates + ')', names: { U: 'U' + base, S: 'S' + base, W: 'SAWANGAN' + base } } }];

