  const cmp = (a, b) => order(a.tab) - order(b.tab) || a.row - b.row;
  items.sort(cmp); unsure.sort(cmp);
  let n = 0; items.forEach(e => e.n = ++n); unsure.forEach(e => e.n = ++n);
  return { items, unsure, unmatched, skipped };
}

